//! Verse of the day for the menu bar: which verse, how it is cut into
//! phrases that fit the bar, and when each phrase appears and dissolves.
//!
//! The verses are compiled in (about 47 KB of text, see
//! `scripts/biblia/extraer_versiculos.py`): no database, no file reads, no
//! network. Picking one is an index into a static table.

/// Generated by `scripts/biblia/extraer_versiculos.py` from the NVI.
const DATA: &str = include_str!("versiculos_nvi.tsv");

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Verse {
    /// Book, chapter and verse, as "Isaías 41:10".
    pub reference: &'static str,
    pub text: &'static str,
}

fn verses() -> impl Iterator<Item = Verse> {
    DATA.lines()
        .filter(|line| !line.is_empty() && !line.starts_with('#'))
        .filter_map(|line| {
            let (reference, text) = line.split_once('\t')?;
            Some(Verse { reference, text })
        })
}

/// How many verses there are; they repeat after this many days.
pub fn count() -> usize {
    verses().count()
}

/// The verse for a day. `day` is any running day number (days since some
/// fixed date, in local time), so consecutive days get consecutive verses
/// and the whole list is shown before any verse repeats.
pub fn of_day(day: i64) -> Verse {
    let count = count().max(1);
    let index = day.rem_euclid(count as i64) as usize;
    verses().nth(index).unwrap_or(Verse {
        reference: "Filipenses 4:13",
        text: "Todo lo puedo en Cristo que me fortalece.",
    })
}

/// One line of the verse as the bar shows it.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Phrase {
    pub text: String,
    /// The last phrase carries the reference after it.
    pub with_reference: bool,
}

/// Cuts `text` into phrases no wider than `max` (as measured by `width`),
/// breaking after punctuation where possible and between words otherwise.
/// The reference, `reference_width` wide, goes after the last phrase, or on
/// its own when it does not fit there.
pub fn phrases(
    text: &str,
    reference_width: f32,
    max: f32,
    width: impl Fn(&str) -> f32,
) -> Vec<Phrase> {
    let mut lines: Vec<String> = Vec::new();
    let mut current = String::new();
    for clause in clauses(text) {
        let joined = join(&current, clause);
        if current.is_empty() || width(&joined) <= max {
            current = joined;
        } else {
            lines.push(std::mem::take(&mut current));
            current = clause.to_owned();
        }
        // A sentence that already fills most of the line ends it, so the
        // next sentence starts its own phrase instead of a sliver of it.
        if ends_sentence(&current) && width(&current) >= max * 0.6 {
            lines.push(std::mem::take(&mut current));
        }
    }
    if !current.is_empty() {
        lines.push(current);
    }
    // A clause can still be too wide on its own: split it between words.
    let lines: Vec<String> = lines
        .into_iter()
        .flat_map(|line| {
            if width(&line) <= max {
                vec![line]
            } else {
                words_to_fit(&line, max, &width)
            }
        })
        .collect();
    let mut phrases: Vec<Phrase> = lines
        .into_iter()
        .map(|text| Phrase {
            text,
            with_reference: false,
        })
        .collect();
    match phrases.last_mut() {
        Some(last) if width(&last.text) + reference_width <= max => last.with_reference = true,
        _ => phrases.push(Phrase {
            text: String::new(),
            with_reference: true,
        }),
    }
    phrases
}

/// Pieces of `text` that each end in punctuation (or at the end).
fn clauses(text: &str) -> Vec<&str> {
    let mut clauses = Vec::new();
    let mut start = 0;
    let mut chars = text.char_indices().peekable();
    while let Some((index, ch)) = chars.next() {
        let next_is_space = chars.peek().is_none_or(|(_, next)| next.is_whitespace());
        if matches!(ch, ',' | ';' | ':' | '.' | '!' | '?') && next_is_space {
            let end = index + ch.len_utf8();
            let clause = text[start..end].trim();
            if !clause.is_empty() {
                clauses.push(clause);
            }
            start = end;
        }
    }
    let rest = text[start..].trim();
    if !rest.is_empty() {
        clauses.push(rest);
    }
    clauses
}

fn join(left: &str, right: &str) -> String {
    if left.is_empty() {
        right.to_owned()
    } else {
        format!("{left} {right}")
    }
}

fn ends_sentence(text: &str) -> bool {
    text.trim_end_matches(['»', '”', ')'])
        .ends_with(['.', '!', '?', ';'])
}

fn words_to_fit(line: &str, max: f32, width: &impl Fn(&str) -> f32) -> Vec<String> {
    let mut out = Vec::new();
    let mut current = String::new();
    for word in line.split_whitespace() {
        let joined = join(&current, word);
        if current.is_empty() || width(&joined) <= max {
            current = joined;
        } else {
            out.push(std::mem::replace(&mut current, word.to_owned()));
        }
    }
    if !current.is_empty() {
        out.push(current);
    }
    out
}

/// When one phrase is on screen, in seconds from the start of the cycle.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Slot {
    /// The letters start to appear, left to right.
    pub start: f32,
    /// The whole phrase is visible.
    pub shown: f32,
    /// It starts to dissolve, left to right.
    pub fading: f32,
    /// Gone.
    pub end: f32,
}

/// The pill fades in for this long before the first phrase.
pub const LEAD_IN: f32 = 0.6;
/// And fades out for this long after the last one.
pub const LEAD_OUT: f32 = 0.8;
const FADE: f32 = 1.3;
const GAP: f32 = 0.35;

/// Timing for phrases of `lengths` characters. Letters appear at a steady
/// pace, each phrase stays long enough to read, then dissolves. Returns the
/// slots and the length of the whole cycle.
pub fn schedule(lengths: &[usize]) -> (Vec<Slot>, f32) {
    let mut at = LEAD_IN;
    let slots = lengths
        .iter()
        .map(|&length| {
            let length = length as f32;
            let reveal = (0.5 + length * 0.022).clamp(0.8, 2.0);
            // About 16 characters a second, never less than a short pause.
            let hold = (1.4 + length / 16.0).min(6.5);
            let slot = Slot {
                start: at,
                shown: at + reveal,
                fading: at + reveal + hold,
                end: at + reveal + hold + FADE,
            };
            at = slot.end + GAP;
            slot
        })
        .collect::<Vec<_>>();
    let total = slots.last().map_or(LEAD_IN, |slot| slot.end) + LEAD_OUT;
    (slots, total)
}

#[cfg(test)]
mod tests {
    use super::*;

    /// A rough stand-in for the bar font: 6.5 px a character.
    fn width(text: &str) -> f32 {
        text.chars().count() as f32 * 6.5
    }

    #[test]
    fn every_verse_is_clean_and_there_is_one_for_each_day_of_the_year() {
        assert_eq!(count(), 366);
        for verse in verses() {
            assert!(!verse.reference.is_empty() && !verse.text.is_empty());
            assert!(
                verse.reference.rsplit_once(' ').is_some_and(|(_, place)| {
                    place.contains(':')
                        && place
                            .chars()
                            .all(|c| c.is_ascii_digit() || ":-".contains(c))
                }),
                "{}",
                verse.reference
            );
            assert!(
                !verse.text.contains(['<', '>', '\t']),
                "{}",
                verse.reference
            );
            assert!(verse.text.chars().count() <= 240, "{}", verse.reference);
        }
    }

    #[test]
    fn consecutive_days_get_consecutive_verses_and_the_list_wraps() {
        let n = count() as i64;
        assert_ne!(of_day(0), of_day(1));
        assert_eq!(of_day(5), of_day(5 + n));
        assert_eq!(of_day(-1), of_day(n - 1));
        let distinct: std::collections::HashSet<_> =
            (0..n).map(|day| of_day(day).reference).collect();
        assert_eq!(distinct.len() as i64, n);
    }

    #[test]
    fn phrases_break_after_punctuation_and_keep_every_word() {
        let text = "Así que no temas, porque yo estoy contigo; no te angusties, porque yo soy tu Dios. Te fortaleceré y te ayudaré; te sostendré con mi diestra victoriosa.";
        let phrases = phrases(text, width("Isaías 41:10"), 300.0, width);
        assert!(phrases.len() >= 3 && phrases.len() <= 6, "{phrases:?}");
        for phrase in &phrases {
            assert!(width(&phrase.text) <= 300.0, "{phrase:?}");
        }
        for phrase in &phrases[..phrases.len() - 1] {
            assert!(phrase.text.ends_with([',', ';', '.']), "{phrase:?}");
        }
        let rejoined = phrases
            .iter()
            .map(|phrase| phrase.text.as_str())
            .filter(|text| !text.is_empty())
            .collect::<Vec<_>>()
            .join(" ");
        assert_eq!(rejoined, text);
        assert!(phrases.last().is_some_and(|last| last.with_reference));
        assert_eq!(
            phrases
                .iter()
                .filter(|phrase| phrase.with_reference)
                .count(),
            1
        );
    }

    #[test]
    fn a_short_verse_is_one_phrase_with_its_reference() {
        let phrases = phrases(
            "Todo lo puedo en Cristo que me fortalece.",
            80.0,
            400.0,
            width,
        );
        assert_eq!(
            phrases,
            [Phrase {
                text: "Todo lo puedo en Cristo que me fortalece.".into(),
                with_reference: true
            }]
        );
    }

    #[test]
    fn the_reference_gets_its_own_phrase_when_the_last_one_is_full() {
        let text = "uno dos tres cuatro cinco seis siete ocho nueve diez once doce";
        let phrases = phrases(text, 120.0, width(text), width);
        assert_eq!(phrases.len(), 2);
        assert!(!phrases[0].with_reference);
        assert_eq!(
            phrases[1],
            Phrase {
                text: String::new(),
                with_reference: true
            }
        );
    }

    #[test]
    fn a_clause_wider_than_the_bar_is_split_between_words() {
        let text = "palabra ".repeat(30);
        let phrases = phrases(text.trim(), 0.0, 120.0, width);
        assert!(phrases.len() > 1);
        assert!(phrases.iter().all(|phrase| width(&phrase.text) <= 120.0));
    }

    #[test]
    fn decimal_and_verse_numbers_do_not_count_as_punctuation() {
        assert_eq!(clauses("Juan 3:16 dice: ama."), ["Juan 3:16 dice:", "ama."]);
    }

    #[test]
    fn every_verse_plays_within_a_minute_and_slots_do_not_overlap() {
        for verse in verses() {
            let phrases = phrases(verse.text, width(verse.reference) + 20.0, 500.0, width);
            let lengths: Vec<usize> = phrases
                .iter()
                .map(|phrase| phrase.text.chars().count() + 12)
                .collect();
            let (slots, total) = schedule(&lengths);
            assert!(total < 58.0, "{} takes {total} s", verse.reference);
            for pair in slots.windows(2) {
                assert!(pair[0].end < pair[1].start);
            }
            for slot in &slots {
                assert!(
                    slot.start < slot.shown && slot.shown < slot.fading && slot.fading < slot.end
                );
            }
        }
    }
}
